import React from 'react';
import './NoticeBar.css'; // Importing the separate CSS file

const NoticeBar = () => {
  const noticeData = {
    badge: "LATEST NOTICE",
    message: "Infinity Laghubitta Bittiya Sanstha Limited: Annual General Meeting (AGM) notice has been published.",
    linkText: "View Details",
    linkUrl: "/investor-relations" 
  };

  return (
    <div className="notice-bar-container">
      <div className="notice-wrapper">
        <span className="notice-badge">{noticeData.badge}</span>
        <p className="notice-message">
          {noticeData.message}
          <a href={noticeData.linkUrl} className="notice-link"> {noticeData.linkText}</a>
        </p>
      </div>
    </div>
  );
};

export default NoticeBar;
